style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url("https://media.discordapp.net/attachments/1358428321511112747/1398200525723537549/fd51adf893be50c0877e47a03ada7412.png?ex=68847f36&is=68832db6&hm=989ab562fb83712d02c55191f4a91ac274298bc458b9b7b5254b9e8e6eb8daaf&=&format=webp&quality=lossless&width=810&height=455");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
  }

  .container-main, .content, .page-content, .rbx-header, .footer, .game-home-page, .game-details-page {
    background-color: rgba(255, 255, 255, 0.8) !important; /* 반투명 흰색 배경 /
    backdrop-filter: blur(5px); / 블러 효과 */
  }
}
